        Assert.That(ship.Runtime.Grants.ContainsSource("item:" + generator.Id, "shieldCapacityBoost"), Is.False); // TEST-SUPPORT: ITEM-EVICTION-20 | Tests: sMPGWM.Tests.ShipItemOwnershipTests.EvictingPrivateEquipmentPreservesConfirmedPublicShipState
        Assert.Throws<KeyNotFoundException>(() => client.Store.GetItem(generator.Id)); // TEST-SUPPORT: ITEM-EVICTION-21 | Tests: sMPGWM.Tests.ShipItemOwnershipTests.EvictingPrivateEquipmentPreservesConfirmedPublicShipState
