        Assert.That(ItemSnapshotCodec.Apply(ItemSnapshotCodec.Encode(host.Player), client.Player), Is.True); // TEST-SUPPORT: ITEM-EVICTION-25 | Tests: sMPGWM.Tests.ShipItemOwnershipTests.EvictingPrivateEquipmentPreservesConfirmedPublicShipState
